architecture_components.config_snippet:
resource "aws_instance" "researchops_ec2" {
  ami           = data.aws_ami.ubuntu.id # Ubuntu 22.04 LTS
  instance_type = var.instance_type      # t3.micro / t3.small
  key_name      = var.key_name
  root_block_device {
    volume_size = 20
    volume_type = "gp3"
  }
}

services:
  api:
    build: { context: ., dockerfile: Dockerfile }
    ports: ["8000:8000"]
    depends_on:
      postgres: { condition: service_healthy }
      redis: { condition: service_healthy }
  devops-showcase:
    build: { context: ./devops-showcase }
    ports: ["8085:80"]

@app.get("/health")
async def liveness(): return {"status": "running"}

@app.get("/ready")
async def readiness(db = Depends(get_db)):
  return OperationsService.get_service_health(db)

worker:
  build: { dockerfile: Dockerfile.worker }
  command: celery -A app.workers.celery_app.celery_app worker -c 2
  depends_on: { redis: { condition: service_healthy } }

server {
  listen 80;
  location / {
    proxy_pass http://api_upstream;
    proxy_read_timeout 300s;
  }
  location /prometheus/ { proxy_pass http://prometheus_upstream/; }
  location /grafana/ { proxy_pass http://grafana_upstream/; }
}
